local a={"Cannon Peripheral Report","========================",""}local function b(c)a[#a+1]=c end;local d=peripheral.getNames()table.sort(d)if#d==0 then b("No peripherals found.")end;for e,f in ipairs(d)do local g={peripheral.getType(f)}local h=peripheral.getMethods(f)or{}table.sort(h)b("Peripheral: "..tostring(f))b("  Types: "..(#g>0 and table.concat(g,", ")or"unknown"))b("  Methods:")for e,i in ipairs(h)do b("    "..tostring(i))end;local j=peripheral.wrap(f)if j and type(j.isWireless)=="function"and type(j.getNamesRemote)=="function"then local k,l=pcall(j.getNamesRemote)b("  Wired network remote peripherals:")if k and type(l)=="table"and#l>0 then table.sort(l)for e,m in ipairs(l)do local n={pcall(j.getTypeRemote,m)}local o=table.remove(n,1)local p,q=pcall(j.getMethodsRemote,m)local r=o and n or{}q=p and q or{}table.sort(q)b("    "..tostring(m))b("      Types: "..(#r>0 and table.concat(r,", ")or"unknown"))b("      Methods: "..(#q>0 and table.concat(q,", ")or"none"))end elseif not k then b("    Could not list remotes: "..tostring(l))else b("    None")end end;b("")end;local s=table.concat(a,"\n")local t=shell.getRunningProgram()local u=fs.combine(fs.getDir(t),"cannon_peripheral_report.txt")local v=fs.open(u,"w")if not v then error("Could not write "..u)end;v.write(s)v.close()print(s)print("\nSaved to "..u)
